import React, { useRef, useMemo, useState, useEffect } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { RoundedBox, Environment } from "@react-three/drei";
import * as THREE from "three";

// ---- Logo face textures (deskewed S / C / m from icon512ai.ai) ----
const TEX_S = "data:image/png;base64,";
const TEX_C = "data:image/png;base64,";
const TEX_M = "data:image/png;base64,";

const BRAND = "#E91825";

/**
 * A single logo face: a transparent PNG (white glyph) rendered on a plane,
 * tinted/lit to sit flush on the cube face.
 */
function useFaceTexture(uri) {
  const [tex, setTex] = useState(null);
  useEffect(() => {
    const loader = new THREE.TextureLoader();
    loader.load(uri, (t) => {
      t.anisotropy = 8;
      t.colorSpace = THREE.SRGBColorSpace;
      t.needsUpdate = true;
      setTex(t);
    });
  }, [uri]);
  return tex;
}

/**
 * OFF+BRAND-style shader material for the cube body:
 * flat brand color + view-dependent fresnel rim + very subtle animated grain,
 * so the red surface feels "alive" as the cube rotates.
 */
function useBodyMaterial() {
  const mat = useMemo(() => {
    const m = new THREE.MeshStandardMaterial({
      color: new THREE.Color(BRAND),
      roughness: 0.42,
      metalness: 0.15,
    });
    m.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = { value: 0 };
      m.userData.shader = shader;
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <common>",
          `#include <common>
           varying vec3 vViewDir;
           varying vec3 vWNormal;`
        )
        .replace(
          "#include <worldpos_vertex>",
          `#include <worldpos_vertex>
           vWNormal = normalize(mat3(modelMatrix) * normal);
           vViewDir = normalize(cameraPosition - worldPosition.xyz);`
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          "#include <common>",
          `#include <common>
           uniform float uTime;
           varying vec3 vViewDir;
           varying vec3 vWNormal;
           float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);} `
        )
        .replace(
          "#include <dithering_fragment>",
          `#include <dithering_fragment>
           float fres = pow(1.0 - clamp(dot(normalize(vViewDir), normalize(vWNormal)),0.0,1.0), 2.4);
           vec3 rim = vec3(1.0, 0.62, 0.45) * fres * 0.55;
           float grain = (hash(gl_FragCoord.xy + uTime) - 0.5) * 0.03;
           gl_FragColor.rgb += rim + grain;`
        );
    };
    return m;
  }, []);
  return mat;
}

function LogoCube({ pointer }) {
  const group = useRef();
  const body = useBodyMaterial();
  const texS = useFaceTexture(TEX_S);
  const texC = useFaceTexture(TEX_C);
  const texM = useFaceTexture(TEX_M);

  // Resting orientation: the classic isometric 3/4 view of the icon.
  const REST_X = -0.62;
  const REST_Y = -0.78;

  useFrame((state, dt) => {
    const t = state.clock.elapsedTime;
    if (body.userData.shader) body.userData.shader.uniforms.uTime.value = t;

    // Gentle idle float + pointer-driven parallax rotation.
    const targetY = REST_Y + pointer.current.x * 0.5 + Math.sin(t * 0.35) * 0.06;
    const targetX = REST_X + pointer.current.y * 0.35 + Math.cos(t * 0.4) * 0.04;
    if (group.current) {
      group.current.rotation.y += (targetY - group.current.rotation.y) * Math.min(1, dt * 3);
      group.current.rotation.x += (targetX - group.current.rotation.x) * Math.min(1, dt * 3);
      group.current.position.y = Math.sin(t * 0.8) * 0.05;
    }
  });

  const S = 2; // cube size
  const off = S / 2 + 0.001;
  const faceMat = (tex) =>
    tex ? (
      <meshStandardMaterial
        map={tex}
        transparent
        roughness={0.35}
        metalness={0.1}
        color={"#ffffff"}
        polygonOffset
        polygonOffsetFactor={-2}
      />
    ) : (
      <meshStandardMaterial transparent opacity={0} />
    );

  return (
    <group ref={group}>
      {/* Cube body */}
      <RoundedBox args={[S, S, S]} radius={0.14} smoothness={6} material={body} castShadow receiveShadow />

      {/* Three visible logo faces (white glyphs float just above each face) */}
      {/* +X face -> C */}
      <mesh position={[off, 0, 0]} rotation={[0, Math.PI / 2, 0]}>
        <planeGeometry args={[S * 0.92, S * 0.92]} />
        {faceMat(texC)}
      </mesh>
      {/* +Y face (top) -> S */}
      <mesh position={[0, off, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[S * 0.92, S * 0.92]} />
        {faceMat(texS)}
      </mesh>
      {/* +Z face (front) -> m */}
      <mesh position={[0, 0, off]}>
        <planeGeometry args={[S * 0.92, S * 0.92]} />
        {faceMat(texM)}
      </mesh>
    </group>
  );
}

function Scene() {
  const pointer = useRef({ x: 0, y: 0 });
  useEffect(() => {
    const onMove = (e) => {
      pointer.current.x = (e.clientX / window.innerWidth - 0.5) * 2;
      pointer.current.y = (e.clientY / window.innerHeight - 0.5) * 2;
    };
    window.addEventListener("pointermove", onMove);
    return () => window.removeEventListener("pointermove", onMove);
  }, []);

  return (
    <>
      <color attach="background" args={["#0a0a0b"]} />
      <ambientLight intensity={0.5} />
      <directionalLight position={[4, 6, 5]} intensity={2.2} castShadow />
      <directionalLight position={[-5, -2, -3]} intensity={0.6} color="#ff6a3d" />
      <Environment preset="studio" />
      <LogoCube pointer={pointer} />
    </>
  );
}

export default function Hero() {
  return (
    <div style={{ position: "relative", width: "100%", height: "100vh", background: "#0a0a0b", overflow: "hidden" }}>
      <Canvas
        shadows
        dpr={[1, 2]}
        camera={{ position: [0, 0, 6], fov: 42 }}
        gl={{ antialias: true, alpha: false }}
      >
        <Scene />
      </Canvas>

      {/* Hero copy overlay */}
      <div style={{
        position: "absolute", inset: 0, display: "flex", flexDirection: "column",
        justifyContent: "flex-end", padding: "6vh 6vw", pointerEvents: "none",
        color: "#fff", fontFamily: "Inter, system-ui, sans-serif",
      }}>
        <div style={{ fontSize: "clamp(11px,1vw,14px)", letterSpacing: "0.3em", opacity: 0.6, marginBottom: 12 }}>
          593 DİJİTAL · SCM
        </div>
        <h1 style={{ margin: 0, fontSize: "clamp(40px,7vw,104px)", lineHeight: 0.95, fontWeight: 700, letterSpacing: "-0.02em" }}>
          Build the<br />
          <span style={{ color: BRAND }}>unbrandable.</span>
        </h1>
      </div>
    </div>
  );
}
